from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    outside = set()
    queue = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in outside:
                outside.add((r, c))
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in outside:
                outside.add((r, c))
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                queue.append((nr, nc))

    seen = set(outside)
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            region = {(r, c)}
            seen.add((r, c))
            queue.append((r, c))
            while queue:
                cr, cc = queue.popleft()
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        region.add((nr, nc))
                        queue.append((nr, nc))
            regions.append(region)

    result = [row[:] for row in grid]
    for region in regions:
        height = max(r for r, _ in region) - min(r for r, _ in region) + 1
        width = max(c for _, c in region) - min(c for _, c in region) + 1
        fill = 2 if height % 2 == 0 and width % 2 == 0 else 7
        for r, c in region:
            result[r][c] = fill
    return result

